import type { Rule, Violation, ShellGuardConfig } from '../types.ts';
import { parseCommand } from '../utils/ps-parser.ts';
import { cdWarningRule } from './cd-warning.ts';
import { sourceCodeSearchRule } from './source-code-search.ts';
import { sourceCodeEditRule } from './source-code-edit.ts';

const rules: Rule[] = [
  sourceCodeEditRule,
  sourceCodeSearchRule,
  cdWarningRule
];

export async function runRules(command: string, config?: ShellGuardConfig): Promise<Violation[]> {
  const parsed = await parseCommand(command);

  const violations: Violation[] = [];
  for (const rule of rules) {
    const violation = rule(parsed, config);
    if (violation) {
      violations.push(violation);
    }
  }
  return violations;
}

export { cdWarningRule, sourceCodeSearchRule, sourceCodeEditRule };
